function useControllable<T>(controlled: T | undefined, defaultValue: T,
                             onChange?: (v: T) => void) {
  const [internal, setInternal] = useState(defaultValue);
  const isControlled = controlled !== undefined;
  const value = isControlled ? controlled : internal;

  const setValue = useCallback((next: T) => {
    if (!isControlled) setInternal(next);      // uncontrolled -> apna state
    onChange?.(next);                          // dono case mein callback
  }, [isControlled, onChange]);

  return [value, setValue] as const;
}

function Select({ value, defaultValue = '', onChange, options }: Props) {
  const [val, setVal] = useControllable(value, defaultValue, onChange);
  return <ul>{options.map(o =>
    <li key={o} aria-selected={val===o} onClick={() => setVal(o)}>{o}</li>)}</ul>;
}

