function Tabs({ defaultValue, children }: Props) {
  const [active, setActive] = useState(defaultValue);
  const tabRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
  const v = useMemo(() => ({ active, setActive, tabRefs }), [active]);
