Tabs.List = ({ children }: PropsWithChildren) => {
  const { tabRefs, active, setActive } = useTabs();
  const onKey = (e: React.KeyboardEvent) => {          // keyboard behaviour hamara
    const ids = [...tabRefs.current.keys()];
    const i = ids.indexOf(active);
    if (e.key === 'ArrowRight') setActive(ids[(i+1) % ids.length]);
    if (e.key === 'ArrowLeft')  setActive(ids[(i-1+ids.length) % ids.length]);
  };
  return <div role="tablist" onKeyDown={onKey}>{children}</div>;
};

Tabs.Tab = ({ value, children }: Props) => {
  const { active, setActive, tabRefs } = useTabs();
  return <button role="tab" aria-selected={active===value}
    tabIndex={active===value ? 0 : -1}                  // roving tabindex
    ref={n => { n ? tabRefs.current.set(value,n) : tabRefs.current.delete(value); }}
    onClick={() => setActive(value)}>{children}</button>;
};

Tabs.Panel = ({ value, children }: Props) =>
  useTabs().active === value ? <div role="tabpanel">{children}</div> : null;

