// normalize
function normalize(apiPosts: ApiPost[]): Store {
  const users: Record<string, User> = {};
  const posts: Record<string, Post> = {};
  const feed: string[] = [];
  for (const p of apiPosts) {
    users[p.author.id] = p.author;                        // dedupe apne aap
    posts[p.id] = { id: p.id, text: p.text, authorId: p.author.id };
    feed.push(p.id);
  }
  return { users, posts, feed };
}

