function Autocomplete({ onSelect }: Props) {
  const [q, setQ] = useState('');
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);           // keyboard highlight
  const debounced = useDebounce(q, 250);

  const { data: items = [] } = useQuery({
    queryKey: ['ac', debounced],
    queryFn: ({ signal }) => api.suggest(debounced, signal),
    enabled: debounced.length >= 2,
    staleTime: 5 * 60_000,                            // 5 min cache
  });

  const onKey = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive(a => Math.min(a+1, items.length-1)); }
    if (e.key === 'ArrowUp')   { e.preventDefault(); setActive(a => Math.max(a-1, 0)); }
    if (e.key === 'Enter' && active >= 0) { onSelect(items[active]); setOpen(false); }
    if (e.key === 'Escape')    { setOpen(false); setActive(-1); }
  };

  return (
    <div role="combobox" aria-expanded={open} aria-haspopup="listbox" aria-owns="ac-list">
      <input value={q} onChange={e => { setQ(e.target.value); setOpen(true); setActive(-1); }}
             onKeyDown={onKey} aria-autocomplete="list"
             aria-activedescendant={active >= 0 ? 'ac-' + active : undefined} />
      {open && (
        <ul id="ac-list" role="listbox">
          {items.map((it, i) => (
            <li key={it.id} id={'ac-' + i} role="option" aria-selected={i === active}
                onMouseDown={e => e.preventDefault()}        // blur se pehle click
                onClick={() => onSelect(it)}>
              {highlight(it.label, debounced)}
            </li>
          ))}
          {!items.length && <li role="option" aria-disabled>Kuch nahi mila</li>}
        </ul>
      )}
    </div>
  );
}

