// focus trap
function useFocusTrap(ref: RefObject<HTMLElement>, active: boolean) {
  useEffect(() => {
    if (!active || !ref.current) return;
    const prev = document.activeElement as HTMLElement;     // kahan the
    const sel = 'a[href],button:not([disabled]),input:not([disabled]),' +
                'select,textarea,[tabindex]:not([tabindex="-1"])';
    const nodes = () => [...ref.current!.querySelectorAll<HTMLElement>(sel)];
    nodes()[0]?.focus();                                     // pehle pe jao

    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;
      const els = nodes(); if (!els.length) return;
      const first = els[0], last = els[els.length-1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    };
    document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('keydown', onKey); prev?.focus(); };  // WAPAS
  }, [active, ref]);
}

