function PhoneInput() {
  const [value, setValue] = useState('');
  const ref = useRef<HTMLInputElement>(null);

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const pos = e.target.selectionStart ?? 0;
    const raw = e.target.value.replace(/\D/g, '');
    const masked = raw.replace(/(\d{5})(\d{0,5})/, '$1 $2').trim();
    const added = masked.length - e.target.value.length;
    setValue(masked);
    requestAnimationFrame(() => {                     // render ke BAAD
      ref.current?.setSelectionRange(pos + added, pos + added);
    });
  };
  return <input ref={ref} value={value} onChange={onChange} inputMode="numeric" />;
}

