function useRealtime(url: string) {
  const [status, setStatus] = useState<'live'|'connecting'|'offline'>('connecting');
  const attempt = useRef(0);
  const queue = useRef<unknown[]>([]);            // offline ke dauraan bheje messages
  const lastId = useRef<string | null>(null);     // gap bharne ke liye

  useEffect(() => {
    let ws: WebSocket, timer: number, alive = true;

    const connect = () => {
      ws = new WebSocket(url + (lastId.current ? '?since=' + lastId.current : ''));

      ws.onopen = () => {
        attempt.current = 0; setStatus('live');
        queue.current.forEach(m => ws.send(JSON.stringify(m)));   // queue flush
        queue.current = [];
      };
      ws.onmessage = e => { const m = JSON.parse(e.data); lastId.current = m.id; apply(m); };
      ws.onclose = () => {
        if (!alive) return;
        setStatus('offline');
        const base = Math.min(1000 * 2 ** attempt.current, 30_000);   // exponential, max 30s
        const delay = base * (0.5 + Math.random() * 0.5);             // JITTER
        attempt.current++;
        timer = window.setTimeout(connect, delay);
      };
    };
    connect();

    // browser ke signals -- reconnect turant
    const onOnline = () => { if (ws.readyState === WebSocket.CLOSED) connect(); };
    window.addEventListener('online', onOnline);
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') onOnline();       // tab wapas aaya
    });

    return () => { alive = false; clearTimeout(timer); ws.close();
      window.removeEventListener('online', onOnline); };
  }, [url]);

  const send = (m: unknown) => status === 'live' ? ws.send(JSON.stringify(m)) : queue.current.push(m);
  return { status, send };
}

type Msg = { id: string; tempId?: string; text: string;
             status: 'sending' | 'sent' | 'failed' };

const send = async (text: string) => {
  const tempId = crypto.randomUUID();
  const optimistic: Msg = { id: tempId, tempId, text, status: 'sending' };

  setMessages(m => [...m, optimistic]);                    // turant dikha do
  try {
    const saved = await api.send({ text, tempId });        // tempId server ko BHEJO
    setMessages(m => m.map(x => x.tempId === tempId
      ? { ...saved, status: 'sent' as const } : x));       // asli id se replace
  } catch {
    setMessages(m => m.map(x => x.tempId === tempId
      ? { ...x, status: 'failed' as const } : x));         // HATAO mat -- retry do
  }
};

// WebSocket echo -- duplicate se bacho
ws.onmessage = e => {
  const incoming: Msg = JSON.parse(e.data);
  setMessages(m => {
    if (incoming.tempId && m.some(x => x.tempId === incoming.tempId))
      return m.map(x => x.tempId === incoming.tempId ? incoming : x);   // replace
    if (m.some(x => x.id === incoming.id)) return m;                    // already hai
    return [...m, incoming];
  });
};

